/** Manifest entry type. */
export type ManifestEntryType = 'File' | 'Directory' | 'Symlink' | 'Hardlink'

/** An entry extracted into memory. */
export interface MemoryEntry {
  /** Entry path, relative, as delivered by extraction. */
  path: string
  /** What the entry is. */
  kind: MemoryEntryKind
  /**
   * The file's bytes as a `Uint8Array` (a plain `Uint8Array`, not a
   * `Buffer`; input parameters accept both); only for a file.
   */
  data?: Uint8Array
  /**
   * Permission bits after setuid and setgid were stripped; only for a file
   * whose archive carries a mode.
   */
  mode?: number
  /**
   * For a symlink, the target as the archive spells it, relative to the
   * link; for a hardlink, the root-relative resolved path of an already
   * delivered entry, a file or an earlier hardlink. Absent for other kinds.
   */
  target?: string
}

/** What a `MemoryEntry` holds. */
export type MemoryEntryKind = 'file' | 'directory' | 'symlink' | 'hardlink'

/** The result of `extractArchiveToMemory`. */
export interface MemoryExtraction {
  /** Extraction statistics. */
  report: ExtractionReport
  /** The extracted entries in path order. */
  entries: Array<MemoryEntry>
}

/**
 * Value of the `writes` property: whether a failed extraction left files on
 * disk.
 */
export type PartialWrites = 'kept' | 'rolled_back' | 'discarded'

/** The path semantics extraction validates names against. */
export type PathModel = 'host' | 'portable'

/**
 * Value of the `relaxableBy` property: the `SecurityConfig` setting whose
 * current value refused the entry.
 */
export type PolicySetting = 'symlinks' | 'hardlinks' | 'solid_archives' | 'banned_components' | 'max_path_depth' | 'windows_reserved_names' | 'max_tar_metadata_bytes'

/** Value of the `subCode` property of a `SECURITY_VIOLATION` error. */
export type SecurityViolationSubCode = 'PATH_NAME' | 'PATH_DEPTH' | 'LINK_TARGET' | 'LINK_POLICY' | 'EXISTING_SYMLINK' | 'ENTRY_TYPE' | 'ROOT_ENTRY' | 'ENCRYPTED' | 'COMPRESSION_METHOD' | 'SOLID_ARCHIVE' | 'DECLARED_SIZE' | 'CONCURRENT_CHANGE' | 'TAR_METADATA' | 'TAR_TRAILER' | 'PLATFORM' | 'OUTPUT_CONFLICT' | 'SOURCE_PATH'

/** Number of items left unverified for one reason. */
export interface UnverifiedCount {
  /** Why the items were not verified. */
  reason: UnverifiedReason
  /** Number of items. */
  count: number
}

/** One entry the integrity check could not verify. */
export interface UnverifiedEntry {
  /** Entry path inside the archive. */
  path: string
  /** Why the entry was not verified. */
  reason: UnverifiedReason
}

/** Why part of the payload was not verified by the integrity check. */
export type UnverifiedReason = 'over_budget' | 'resource_limit' | 'solid_policy' | 'size_ceiling' | 'uncovered_block_crc' | 'not_decodable' | 'no_end_marker' | 'path_too_long' | 'descriptor_tail'

/** Single verification issue. */
export interface VerificationIssue {
  /** Issue severity level. */
  severity: IssueSeverity
  /** Issue category. */
  category: IssueCategory
  /** Entry path that triggered issue (if applicable). */
  entryPath?: string
  /** Human-readable description. */
  message: string
  /** Optional context (compression ratio, target path, etc.). */
  context?: string
}

/**
 * Result of archive verification.
 *
 * Generated by `verifyArchive()`, contains the result of the security checks
 * performed without extracting files to disk.
 */
export interface VerificationReport {
  /** Overall verification status. */
  status: VerificationStatus
  /** Integrity check result. */
  integrityStatus: IntegrityStatus
  /**
   * What the integrity check left unverified; absent unless the check was
   * requested.
   */
  integrityGaps?: IntegrityGaps
  /** Security check result. */
  securityStatus: CheckStatus
  /** List of all issues found (sorted by severity). */
  issues: Array<VerificationIssue>
  /** Total entries scanned. */
  totalEntries: number
  /** Entries flagged as suspicious. */
  suspiciousEntries: number
  /** Total uncompressed size. */
  totalSize: number
  /** Archive format. */
  format: ArchiveType
}

/** Overall verification status. */
export type VerificationStatus = 'PASS' | 'FAIL' | 'WARNING'

/**
 * Verify archive security (async).
 *
 * # Arguments
 *
 * * `archive_path` - Path to archive file
 * * `config` - Optional `SecurityConfig` (uses secure defaults if omitted)
 * * `options` - Optional `VerificationOptions`; use `new
 *   VerificationOptions().withIntegrityCheck()` to decode the payload and
 *   verify checksums (default: metadata only, `integrityStatus` is
 *   `'SKIPPED'`)
 *
 * # Returns
 *
 * Promise resolving to `VerificationReport` with validation results
 *
 * # Errors
 *
 * Returns error if path validation fails, archive is invalid, or I/O errors
 * occur. With the integrity check on, a TAR entry whose content fails to
 * decode is also an error.
 *
 * # Examples
 *
 * ```javascript
 * const report = await verifyArchive('archive.tar.gz');
 * if (report.status === 'PASS') {
 *     console.log('Archive is safe to extract');
 * } else {
 *     for (const issue of report.issues) {
 *         console.log(`[${issue.severity}] ${issue.message}`);
 *     }
 * }
 * ```
 */
export declare function verifyArchive(archivePath: string, config?: SecurityConfig | undefined | null, options?: VerificationOptions | undefined | null): Promise<VerificationReport>

